"""Report frozen cold-envelope results; no changes to learners or calibration."""

import json
from .pipeline import ROOT


def write_report(summary, directory):
    s = summary["selection"]; e = summary["envelope"]
    lines = ["# Диапазон ошибки на холодных ночах", "",
             "Дата: 13 октября 2026 года. Станция Краснодар34929, март–май, не выбранный сад.",
             "Расширение снизило штраф за ошибку границ на холодных ночах2025, но покрытие осталось3/6. В2026 покрытие осталось4/4, а штраф немного вырос из-за большей ширины. Устойчивого улучшения покрытия холодных событий не установлено; полевой прогноз остаётся GFS.", "",
             "## Протокол до контрольных лет", "",
             "Семь вариантов и критерий зафиксированы до нового расчёта2025/2026. Точечная Huber-модель и детектор event_duration_weather@0.25 сохранены. Для выбора диапазона: fit2022→валидация2023, fit2022–23→валидация2024. Калибровка внутри каждого валидационного сезона исключает проверяемую ночь целиком из глобального и прогнозного рискового пула.",
             "Это ретроспективная leave-one-night-out диагностика для выбора, а не перспективный прогноз каждой валидационной ночи: другие даты того же сезона, включая более поздние, доступны калибровке. Настройки выбираются по холодному непокрытию, затем сбалансированному interval score холодных/тёплых ночей и ширине. Калибровочный2024 используется и в выборе настроек, поэтому независимой гарантии калибровки не заявляем.",
             "Финальная калибровка — только полные ночи2024, контроль2025/2026 не входит ни в подбор, ни в калибровку. Эти контрольные годы ранее просмотрены, новым слепым тестом не называются.", "",
             "## Выбор на2023–2024", "",
             "| Вариант | Холодных покрыто | Средняя ширина, °C | Interval score холодных | Interval score тёплых |",
             "|---|---:|---:|---:|---:|"]
    for name, r in s["pooled_validation"].items():
        lines.append(f"| {name} | {r['cold_covered']}/{r['cold_nights']} | {r['mean_width_c']:.3f} | {r['cold_interval_score']:.3f} | {r['warm_interval_score']:.3f} |")
    lines += ["", "Выбран "+s["winner"]+". Группа определяется до факта: min(минимум Huber, минимум GFS) ≤5°C. Расширяется только нижняя граница; верхняя и тёплые прогнозы сохраняют прежний диапазон.",
              f"Финальный глобальный пул: {e['pool_nights']} ночей; рисковый: {e['risk_pool_nights']} — меньше30. Применён заранее заданный fallback к глобальному пулу, без фиктивной калибровки на малой группе. Нижний радиус {e['base_radius_c']:.3f}→{e['lower_radius_c']:.3f}°C, верхний {e['upper_radius_c']:.3f}°C.",
              "Новые границы содержат прежний диапазон для каждой ночи. Это обеспечивает неухудшение наблюдаемого покрытия при неизменном точечном прогнозе, но не гарантирует рост покрытия или лучшую полезность.", "",
              "## Контрольные годы", "",
              "| Год | Метод | Ночей | Покрытие всех | Покрытие холодных | Средняя ширина, °C | Ширина холодных, °C | Interval score холодных |",
              "|---|---|---:|---:|---:|---:|---:|---:|"]
    for year, season in summary["seasons"].items():
        for name, r in season["scores"].items():
            lines.append(f"| {year} | {name} | {r['nights']} | {r['covered']}/{r['nights']} | {r['cold_covered']}/{r['cold_nights']} | {r['mean_width_c']:.3f} | {r['cold_mean_width_c']:.3f} | {r['cold_interval_score']:.3f} |")
    lines += ["", "Interval score рассчитан с общим alpha=0.1 для всех вариантов: ширина +20×выход факта за границу. Меньше лучше. Он не является денежным ущербом.", "",
              "## Детектор сохранён", "", "| Год | Попадания | Пропуски | Ложные тревоги | Проверено полных прогнозных масок |", "|---|---:|---:|---:|---:|"]
    for year, season in summary["seasons"].items():
        c = season["detector"]
        lines.append(f"| {year} | {c.get('hits',0)} | {c.get('misses',0)} | {c.get('false_alarms',0)} | {season['detector_masks_verified']} |")
    lines += ["", "Проверены совпадение всех14-битных масок с прежним snapshot, начала/длительности и точечного минимума. Изменение диапазона не меняет тревогу детектора. Расширение диапазона, пересекающего0°C, не создаёт автоматически новую тревогу.",
              "Все сложные прогнозы и экстраполяции сохранены в сравнении; неполные факты не заполняются. Старая защита области применения сохранена через safe_cold_envelope: другой сайт, сезон, горизонт, плохие признаки или сильная экстраполяция дают отсутствие скорректированного ответа.", "",
              "## Вывод и ограничения", "",
              "На семи валидационных холодных ночах расширение выглядело успешным, но на шести холодных ночах2025 новые границы не покрыли ни одного дополнительного случая. Штраф2025 уменьшился за счёт сокращения расстояния до нижней границы; две нижние и одна верхняя ошибки остаются. В2026 добавлено покрытие одной тёплой ночи, на холодных изменений нет.",
              "Общая ширина растёт примерно на0.12–0.13°C, на холодных — на0.40°C. Пересечений диапазона с0 становится больше, что увеличивает неопределённость для оператора; ложные тревоги неизменного детектора не растут. Улучшение interval score в одном сезоне не выдаём за устойчивый выигрыш.",
              "На малом количестве холодных событий нет основания обещать условное90% покрытие, вероятность повреждений или перенос в неизвестный сад. Методологический источник: [Vovk2012 о разных видах условной валидности](https://proceedings.mlr.press/v25/vovk12). Группировка здесь прогнозная; фактическое условие «ночь холодная» не известно на момент прогноза.",
              "Следующее исследование должно проверять условную модель масштаба/хвостов ошибок с новым заранее записанным протоколом и перспективными данными. Выбранные сейчас настройки не переключались по контрольным2025/2026.", "",
              "## Воспроизведение", "",
              "    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker cold-interval-select --offline",
              "    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker cold-interval-study --offline", "",
              "SHA выбора: "+summary["selection_sha256"]+".",
              "SHA исходных прогнозов: "+summary["legacy_forecast_sha256"]+".",
              "SHA исходных масок: "+summary["legacy_mask_sha256"]+".",
              "[Численная сводка](COLD_INTERVAL_SUMMARY.json). [Предыдущая модель](MINIMUM_STUDY_REPORT.md)."]
    (directory/"COLD_INTERVAL_REPORT.md").write_text("\n".join(lines)+"\n", encoding="utf-8")


def build_viewer(summary, data_dir):
    from .scenario_study import sha
    path = data_dir/"processed/cold-interval-study/night-forecasts.json"
    if sha(path) != summary["forecast_sha256"]: raise ValueError("Cold interval snapshot changed")
    payload = {"summary": summary, "frames": json.loads(path.read_text(encoding="utf-8"))}
    text = (ROOT/"web/cold-range/index.html").read_text(encoding="utf-8")
    output = ROOT/"dist/cold-range"; output.mkdir(parents=True, exist_ok=True)
    (output/"index.html").write_text(text.replace("__COLD_DATA__", json.dumps(payload, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c")), encoding="utf-8")
